server {
    listen 80;
    root /usr/share/nginx/html;
    index index.html;

    # Proxy v2 Laravel API  (/php/hrm-laravel/public/ → container api)
    location /php/hrm-laravel/public/ {
        proxy_pass         http://api/;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_read_timeout 120s;
    }

    # Fichiers stockage Laravel (photos employés, storage:link)
    location /storage/ {
        proxy_pass       http://api/storage/;
        proxy_set_header Host $host;
    }

    # SPA — toute autre URL → index.html
    location / {
        try_files $uri $uri/ /index.html;
    }
}

