import { createRouter, createWebHistory } from 'vue-router'
import { useAuthStore } from '@/stores/auth'

const routes = [
  { path: '/login', component: () => import('@/views/auth/LoginView.vue'), meta: { public: true } },

  {
    path: '/',
    component: () => import('@/components/layout/AppLayout.vue'),
    meta: { requiresAuth: true },
    children: [
      { path: '',          redirect: '/dashboard' },
      { path: 'dashboard', component: () => import('@/views/DashboardView.vue') },

      { path: 'employees',          component: () => import('@/views/employees/EmployeeListView.vue') },
      { path: 'employees/new',      component: () => import('@/views/employees/EmployeeFormView.vue'),   meta: { role: 'hr' } },
      { path: 'employees/:id',      component: () => import('@/views/employees/EmployeeDetailView.vue') },
      { path: 'employees/:id/edit', component: () => import('@/views/employees/EmployeeFormView.vue'),   meta: { role: 'hr' } },

      { path: 'departments',     component: () => import('@/views/departments/DepartmentListView.vue') },
      { path: 'departments/:id', component: () => import('@/views/departments/DepartmentDetailView.vue') },

      { path: 'skills',        component: () => import('@/views/skills/SkillListView.vue') },
      { path: 'skills-matrix', component: () => import('@/views/skills/SkillsMatrixView.vue') },

      { path: 'projects',          component: () => import('@/views/projects/ProjectListView.vue') },
      { path: 'projects/new',      component: () => import('@/views/projects/ProjectFormView.vue'),   meta: { role: 'hr_manager' } },
      { path: 'projects/:id',      component: () => import('@/views/projects/ProjectDetailView.vue') },
      { path: 'projects/:id/edit', component: () => import('@/views/projects/ProjectFormView.vue'),   meta: { role: 'hr_manager' } },

      { path: 'reviews',          component: () => import('@/views/reviews/ReviewListView.vue') },
      { path: 'reviews/new',      component: () => import('@/views/reviews/ReviewFormView.vue'),   meta: { role: 'hr_manager' } },
      { path: 'reviews/:id',      component: () => import('@/views/reviews/ReviewDetailView.vue') },

      { path: 'users',    component: () => import('@/views/users/UserListView.vue'),     meta: { role: 'hr' } },
      { path: 'security', component: () => import('@/views/security/SecurityView.vue') },
    ],
  },

  { path: '/:pathMatch(.*)*', redirect: '/' },
]

const router = createRouter({
  history: createWebHistory(),
  routes,
})

router.beforeEach((to) => {
  const auth = useAuthStore()

  if (to.meta.public) return true

  if (!auth.isLoggedIn) return '/login'

  if (to.meta.role === 'hr'         && auth.role !== 'hr')                                  return '/dashboard'
  if (to.meta.role === 'hr_manager' && auth.role !== 'hr' && auth.role !== 'manager')       return '/dashboard'

  // Employee : accès restreint aux données personnelles uniquement
  if (auth.role === 'employee') {
    // /employees → redirige vers son propre profil
    if (to.path === '/employees') {
      return auth.employeeId ? `/employees/${auth.employeeId}` : '/dashboard'
    }
    // /employees/:id → bloque si ce n'est pas son propre profil
    if (to.params.id && to.path.startsWith('/employees/') && !to.path.endsWith('/edit')) {
      if (Number(to.params.id) !== auth.employeeId) return '/dashboard'
    }
  }

  return true
})

export default router

