import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import http from '@/api/http'

export const useAuthStore = defineStore('auth', () => {
  // Read from localStorage first (remember me), then sessionStorage (session only)
  const user = ref(
    JSON.parse(
      localStorage.getItem('hrm_user') ||
      sessionStorage.getItem('hrm_user') ||
      'null'
    )
  )

  const isLoggedIn  = computed(() => user.value !== null)
  const role        = computed(() => user.value?.role ?? '')
  const isHr        = computed(() => role.value === 'hr')
  const isManager   = computed(() => role.value === 'manager')
  const isEmployee  = computed(() => role.value === 'employee')
  const employeeId  = computed(() => user.value?.employee_id ?? null)
  const jobTitle    = computed(() => user.value?.job_title ?? null)

  async function login(email, password, remember = false) {
    const { data } = await http.post('/auth/login', { email, password })
    user.value = data.data
    if (remember) {
      localStorage.setItem('hrm_user', JSON.stringify(data.data))
      sessionStorage.removeItem('hrm_user')
    } else {
      sessionStorage.setItem('hrm_user', JSON.stringify(data.data))
      localStorage.removeItem('hrm_user')
    }
  }

  async function logout() {
    try { await http.post('/auth/logout') } catch {}
    clear()
  }

  function clear() {
    user.value = null
    localStorage.removeItem('hrm_user')
    sessionStorage.removeItem('hrm_user')
  }

  return { user, isLoggedIn, role, isHr, isManager, isEmployee, employeeId, jobTitle, login, logout, clear }
})
